import json,datetime,pathlib
root=pathlib.Path('.')
r=json.loads((root/'run.json').read_text());end=datetime.datetime.now(datetime.timezone.utc)
r.update(status='completed',ended_at=end.isoformat());r['usage']['wall_time_seconds']=(end-datetime.datetime.fromisoformat(r['started_at'])).total_seconds()
r['attempts']=[{'attempt':1,'path':'artifacts/attempt-01','outcome':'generated; ERC and physical DRC passed, eight schematic parity warnings','logs':['logs/generate-01.log','logs/validate-01.log','logs/erc-01.json','logs/drc-01.json']},{'attempt':2,'path':'artifacts/attempt-02','outcome':'completed; ERC, DRC, connectivity, parity and exports passed','logs':['logs/repair-02.log','logs/validate-02.log','logs/erc-02.json','logs/drc-02.json','logs/geometry-02.log']}]
files=sorted(str(p) for p in (root/'artifacts').rglob('*') if p.is_file());r['artifacts']=files;r['failure']=None
(root/'run.json').write_text(json.dumps(r,indent=2)+'\n')
result={'status':'completed','final_attempt':'artifacts/attempt-02','generated_files':files,'validation':{'erc':{'passed':True,'violations':0,'log':'logs/erc-02.json'},'drc':{'passed':True,'violations':0,'unconnected_items':0,'schematic_parity_issues':0,'log':'logs/drc-02.json'},'exports':{'schematic_svg_exit_code':0,'schematic_netlist_exit_code':0,'pcb_svg_exit_code':0,'log':'logs/validate-02.log'},'geometry_and_topology':{'passed':True,'log':'logs/geometry-02.log'},'physical_testing':None},'known_limitations':['No physical testing or simulation.','No visual GUI review; native SVG exports retained.','Generic standard library components; exact manufacturer parts unspecified.','Library tables contain machine-specific installed library paths.','Headless pcbnew wxApp assertion diagnostic retained; CLI validation exits zero.','Default KiCad ignored checks recorded verbatim in ERC and DRC JSON.'],'failure':None,'started_at':r['started_at'],'ended_at':r['ended_at'],'wall_time_seconds':r['usage']['wall_time_seconds']}
(root/'result.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps({'status':r['status'],'wall_time_seconds':r['usage']['wall_time_seconds'],'final_attempt':result['final_attempt']},indent=2))
